/// Writes the CityCore Swift for validated game data, keyed by file name.
/// Output depends only on the data: cases follow load order and goods
/// inside a value are sorted by id, so two runs are byte-identical.
public enum SwiftEmitter {
    /// The first words of every generated file.
    public static let marker = "// GENERATED by gamedata-gen"

    public static let banner = """
    \(marker) from Packages/CityCore/GameData.
    // Do not edit: change the packs, then run `make gamedata`.
    // swiftlint:disable superfluous_disable_command cyclomatic_complexity file_length line_length type_body_length

    import Foundation

    """

    /// Re-enables the lint rules the banner disables: one exhaustive
    /// switch per value breaks them by design.
    static let footer = "\n// swiftlint:enable superfluous_disable_command cyclomatic_complexity file_length line_length type_body_length\n"

    /// One public file per content type, or, with a `namespace`, a single
    /// file that nests every internal type in `enum <namespace>`. The
    /// namespace lets the generated catalogs sit next to the hand-written
    /// ones during the migration (design D8).
    public static func emit(_ data: GameData, namespace: String? = nil) -> [String: String] {
        let types = Types(data: data, access: namespace == nil ? "public " : "")
        let files = [
            ("Good+Generated.swift", types.goods + types.goodsCatalog),
            ("BuildingKind+Generated.swift", types.buildingKind + types.buildingCatalog),
            ("ProductionCatalog+Generated.swift", types.productionCatalog),
            ("Culture+Generated.swift", types.culture),
            ("Tech+Generated.swift", types.tech),
            ("Age+Generated.swift", types.age),
            ("HouseTier+Generated.swift", types.houseTier),
            ("OrderTemplate+Generated.swift", types.orderTemplate),
            ("SeasonalEvent+Generated.swift", types.seasonalEvent),
            ("Logistics+Generated.swift", types.logistics + types.vehicle),
            ("Campaign+Generated.swift", ChapterEmitter(data: data, access: types.access).catalog)
        ]
        guard let namespace else {
            return Dictionary(uniqueKeysWithValues: files.map { ($0.0, banner + $0.1 + footer) })
        }
        let indented = files.map(\.1).joined().split(separator: "\n", omittingEmptySubsequences: false)
            .map { $0.isEmpty ? "" : "    " + $0 }.joined(separator: "\n")
        return ["\(namespace).swift": banner + "\nenum \(namespace) {" + indented + "}\n" + footer]
    }
}

// MARK: - Names

/// Swift's reserved words plus its contextual keywords. Back-quoting a
/// word that needs no quotes is still valid Swift, so the list errs on
/// the side of quoting.
private let keywords: Set<String> = [
    "actor", "any", "as", "associatedtype", "async", "await", "borrowing", "break", "case", "catch", "class",
    "consume", "consuming", "continue", "convenience", "copy", "default", "defer", "deinit", "didSet", "discard",
    "do", "dynamic", "each", "else", "enum", "extension", "fallthrough", "false", "fileprivate", "final", "for",
    "func", "get", "guard", "if", "import", "in", "indirect", "infix", "init", "inout", "internal", "is", "isolated",
    "lazy", "let", "macro", "mutating", "nil", "nonisolated", "nonmutating", "open", "operator", "optional",
    "override", "package", "postfix", "precedencegroup", "prefix", "private", "protocol", "public", "repeat",
    "required", "rethrows", "return", "self", "set", "some", "static", "struct", "subscript", "super", "switch",
    "throw", "throws", "true", "try", "typealias", "unowned", "var", "weak", "where", "while", "willSet"
]

/// The Swift case for an id; keywords are back-quoted.
func caseName(_ id: String) -> String {
    let name = unquotedCaseName(id)
    return keywords.contains(name) ? "`\(name)`" : name
}

/// `lumberjack-hut` → `lumberjackHut`. Distinct ids can share one, e.g.
/// `salt-1` and `salt1`, which the validator rejects.
func unquotedCaseName(_ id: String) -> String {
    let words = id.split(separator: "-")
    return (words.first.map(String.init) ?? "") + words.dropFirst().map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined()
}

/// `grain-farm` → `Grain Farm`.
private func titleCased(_ id: String) -> String {
    id.split(separator: "-").map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined(separator: " ")
}

/// `[.planks: 1, .wood: 4]`, sorted by good id.
func amounts(_ amounts: GoodAmounts) -> String {
    guard !amounts.isEmpty else { return "[:]" }
    return "[" + amounts.sorted { $0.good < $1.good }.map { ".\(caseName($0.good)): \($0.amount)" }.joined(separator: ", ") + "]"
}

func optionalCase(_ id: String?) -> String {
    id.map { ".\(caseName($0))" } ?? "nil"
}

func caseList(_ ids: [String]) -> String {
    "[" + ids.map { ".\(caseName($0))" }.joined(separator: ", ") + "]"
}

func literal(_ text: String) -> String {
    String(reflecting: text)
}

/// The declaration of each generated type. `access` prefixes every
/// declaration: `public ` for the real catalogs, empty in a namespace.
private struct Types {
    let data: GameData
    let access: String

    var goods: String {
        let all = data.goods
        return enumDecl("Good", "String, CaseIterable, Codable, Sendable", all.map(\.id), [
            property("basePrice", "Int64", all.map { ($0.id, "\($0.basePrice)") }),
            property("marketTerms", "MarketTerms", all.map { good in
                (good.id, "MarketTerms(buyLimit: \(good.market.buy), sellLimit: \(good.market.sell))")
            })
        ])
    }

    var goodsCatalog: String {
        catalog("GoodsCatalog", spec: "GoodSpec", for: "good", of: "Good", data.goods.map { good in
            (good.id, "GoodSpec(good: .\(caseName(good.id)), displayName: \(literal(good.name)), stackUnit: \(literal(good.unit)))")
        })
    }

    var buildingKind: String {
        let all = data.buildings
        return enumDecl("BuildingKind", "String, CaseIterable, Codable, Sendable", all.map(\.id), [
            codable(aliases: all.flatMap { building in building.legacyIds.map { ($0, building.id) } }),
            property("displayName", "String", all.map { ($0.id, literal($0.name ?? titleCased($0.id))) }),
            property("storage", "Int?", all.map { ($0.id, $0.storage.map(String.init) ?? "nil") }),
            property("storagePerGood", "Int?", all.map { ($0.id, $0.storagePerGood.map(String.init) ?? "nil") }),
            property("plantTicks", "UInt64?", all.map { ($0.id, $0.plantTicks.map(String.init) ?? "nil") }),
            property("catchmentRadius", "Int?", all.map { ($0.id, $0.catchmentRadius.map(String.init) ?? "nil") }),
            property("category", "String?", all.map { ($0.id, $0.category.map(literal) ?? "nil") }),
            property("culture", "Culture?", all.map { ($0.id, optionalCase($0.culture)) }),
            property("obsoletedBy", "Tech?", all.map { ($0.id, optionalCase($0.obsoletedBy)) }),
            property("accepts", "Set<Good>?", all.map { ($0.id, $0.accepts.map { caseList($0.sorted()) } ?? "nil") }),
            property("isCrop", "Bool", all.map { ($0.id, "\($0.isCrop)") }),
            property("hub", "HubSpec?", all.map { ($0.id, $0.hub.map(hubSpec) ?? "nil") })
        ])
    }

    var buildingCatalog: String {
        catalog("BuildingCatalog", spec: "BuildingSpec", for: "kind", of: "BuildingKind", data.buildings.map { ($0.id, spec($0)) })
    }

    var productionCatalog: String {
        let recipes = data.buildings.map { building in (building.id, building.recipe.map(recipe) ?? "nil") }
        return "\n\(access)enum ProductionCatalog {\n"
            + function("\(access)static func recipe(for kind: BuildingKind) -> ProductionRecipe?", over: "kind", recipes)
            + "}\n"
    }

    var culture: String {
        let all = data.cultures
        let tierNames = all.flatMap { culture in
            data.tiers.map { tier in
                ("(.\(caseName(culture.id)), .\(caseName(tier.id)))", literal(culture.tierName(tier)))
            }
        }
        return enumDecl("Culture", "String, CaseIterable, Codable, Hashable, Sendable", all.map(\.id), [
            property("displayName", "String", all.map { ($0.id, literal($0.name)) }),
            property("blurb", "String", all.map { ($0.id, literal($0.blurb)) }),
            property("luxuryChain", "LuxuryChain", all.map { ($0.id, luxury($0.luxury)) }),
            property("signature", "BuildingKind", all.map { ($0.id, ".\(caseName($0.signature))") }),
            property("residentNames", "[String]", all.map { ($0.id, "[\($0.residentNames.map(literal).joined(separator: ", "))]") }),
            tierNames.isEmpty ? "" : function(
                "\(access)func tierName(_ tier: HouseTier) -> String",
                over: "(self, tier)",
                tierNames,
                quoted: false
            )
        ])
    }

    var tech: String {
        let all = data.techs
        return enumDecl("Tech", "String, CaseIterable, Codable, Sendable", all.map(\.id), [
            property("displayName", "String", all.map { ($0.id, literal($0.name ?? titleCased($0.id))) }),
            property("cost", "Int", all.map { ($0.id, "\($0.cost)") }),
            property("prerequisites", "[Tech]", all.map { ($0.id, caseList($0.prerequisites)) }),
            property("unlocks", "[BuildingKind]", all.map { ($0.id, caseList(data.unlocks(of: $0.id))) }),
            property("age", "Age", all.map { ($0.id, ".\(caseName($0.age))") }),
            property("era", "Age?", all.map { ($0.id, optionalCase($0.era)) }),
            property("eraGate", "(tier: HouseTier, residents: Int)?", all.map { tech in
                (tech.id, tech.eraGate.map { "(.\($0.tier), \($0.residents))" } ?? "nil")
            })
        ])
    }

    var age: String {
        let all = data.ages
        return enumDecl("Age", "String, CaseIterable, Codable, Hashable, Sendable", all.map(\.id), [
            property("displayName", "String", all.map { ($0.id, literal($0.name ?? titleCased($0.id))) }),
            property("startYear", "Int", all.map { ($0.id, "\($0.startYear)") }),
            property("blurb", "String", all.map { ($0.id, literal($0.blurb)) }),
            property("signature", "BuildingKind", all.map { ($0.id, ".\(caseName($0.signature))") }),
            property("rivalResidents", "Int", all.map { ($0.id, "\($0.rivalResidents)") }),
            property("orderEvery", "Int", all.map { ($0.id, "\($0.orderEvery)") })
        ])
    }

    var orderTemplate: String {
        let all = data.orders
        return enumDecl("OrderTemplate", "String, CaseIterable, Codable, Sendable", all.map(\.id), [
            property("issuer", "OrderIssuerKind", all.map { ($0.id, ".\(caseName($0.issuer))") }),
            property("good", "Good", all.map { ($0.id, ".\(caseName($0.good))") }),
            property("title", "String", all.map { ($0.id, literal($0.title)) }),
            property("text", "String", all.map { ($0.id, literal($0.text)) }),
            property("minAge", "Age?", all.map { ($0.id, optionalCase($0.minAge)) }),
            property("seasons", "Int", all.map { ($0.id, "\($0.seasons)") }),
            property("sizePercent", "Int", all.map { ($0.id, "\($0.size)") }),
            property("minUnits", "Int", all.map { ($0.id, "\($0.min)") }),
            property("maxUnits", "Int", all.map { ($0.id, "\($0.max)") }),
            property("rewardPercent", "Int", all.map { ($0.id, "\($0.reward)") }),
            property("favourGain", "Int", all.map { ($0.id, "\($0.favour)") }),
            property("favourLoss", "Int", all.map { ($0.id, "\($0.penalty)") })
        ])
    }

    var seasonalEvent: String {
        let all = data.events
        let firstAge = data.ages.first?.id ?? ""
        return enumDecl("SeasonalEvent", "String, CaseIterable, Codable, Sendable", all.map(\.id), [
            property("effect", "SeasonalEffect", all.map { ($0.id, ".\(caseName($0.effect))") }),
            property("seasons", "[Season]", all.map { ($0.id, caseList($0.seasons)) }),
            property("minAge", "Age", all.map { ($0.id, ".\(caseName($0.minAge ?? firstAge))") }),
            property("weights", "[Difficulty: Int]", all.map { event in
                (event.id, "[" + ItemSchema.difficulties.map { ".\($0): \(event.weights[$0] ?? 0)" }.joined(separator: ", ") + "]")
            }),
            property("banners", "[SeasonalBannerKind: SeasonalBanner]", all.map { ($0.id, banners($0.banners)) }),
            property("isEnabled", "Bool", all.map { ($0.id, "\($0.enabled)") }),
            property("firstYear", "Int", all.map { ($0.id, "\($0.firstYear)") }),
            property("minFoodSeasons", "Int", all.map { ($0.id, "\($0.minFoodSeasons)") })
        ])
    }

    /// Raw values are positions from 1: saves store them, and `next` and
    /// `previous` step through them (design D1 of `tier-needs-data`).
    var houseTier: String {
        let all = data.tiers
        return enumDecl("HouseTier", "UInt8, CaseIterable, Codable, Sendable", all.map(\.id), rawValues: all.indices.map { "\($0 + 1)" }, [
            property("capacity", "UInt32", all.map { ($0.id, "\($0.capacity)") }),
            property("needs", "[Good]", all.map { ($0.id, caseList($0.needs)) }),
            property("taxPerResident", "Int64", all.map { ($0.id, "\($0.taxPerResident)") }),
            property("declineGrace", "Int", all.map { ($0.id, "\($0.declineGrace)") }),
            property("displayName", "String", all.map { ($0.id, literal($0.name)) })
        ])
    }

    /// The distribution tunables as constants.
    var logistics: String {
        guard let values = data.logistics.first else { return "" }
        return """

        \(access)enum LogisticsCatalog {
            /// Road tiles a haul must cover before it takes a vehicle.
            \(access)static let haulDistance = \(values.haulDistance)
            /// Units that must be ready for one destination before a vehicle goes.
            \(access)static let haulMinLoad = \(values.haulMinLoad)
            /// Ticks a producer's output waits for a vehicle load before it goes anyway.
            \(access)static let haulMaxWait = \(values.haulMaxWait)
            /// Consumptions of each need a house keeps in stock.
            \(access)static let houseStockConsumptions = \(values.houseStockConsumptions)
            /// Units of each need a house stock holds at least.
            \(access)static let houseStockMinimum = \(values.houseStockMinimum)
        }

        """
    }

    /// The vehicles, in load order, with their first age and capacity.
    var vehicle: String {
        let all = data.vehicles
        guard !all.isEmpty else { return "" }
        return enumDecl("Vehicle", "String, CaseIterable, Codable, Hashable, Sendable", all.map(\.id), [
            property("age", "Age", all.map { ($0.id, ".\(caseName($0.age))") }),
            property("capacity", "Int", all.map { ($0.id, "\($0.capacity)") })
        ])
    }

    // MARK: - Values

    private func hubSpec(_ hub: Hub) -> String {
        "HubSpec(radius: \(hub.radius), housesPerPorter: \(hub.housesPerPorter), maxPorters: \(hub.maxPorters), "
            + "basketUnits: \(hub.basketUnits), reserveConsumptions: \(hub.reserveConsumptions))"
    }

    private func spec(_ building: Building) -> String {
        var shore = "nil", terrain = "nil"
        switch building.placement {
        case let .shore(land, water)?: shore = "ShorePlacement(minLandTiles: \(land), minWaterTiles: \(water))"
        case let .terrain(type, tiles)?: terrain = "TerrainRequirement(terrain: .\(type), minTiles: \(tiles))"
        case nil: break
        }
        return "BuildingSpec(kind: .\(caseName(building.id)), "
            + "footprint: Footprint(width: \(building.footprint.width), height: \(building.footprint.height)), "
            + "cost: \(building.cost), upkeep: \(building.upkeep), buildDurationTicks: \(building.buildTicks), "
            + "shorePlacement: \(shore), materialCost: \(amounts(building.materials)), requiredTerrain: \(terrain))"
    }

    private func recipe(_ recipe: Recipe) -> String {
        "ProductionRecipe(inputs: \(amounts(recipe.inputs)), outputs: \(amounts(recipe.outputs)), cycleTicks: \(recipe.cycleTicks))"
    }

    private func luxury(_ chain: LuxuryChain) -> String {
        "LuxuryChain(raw: .\(caseName(chain.raw)), good: .\(caseName(chain.good)), "
            + "garden: .\(caseName(chain.garden)), producer: .\(caseName(chain.producer)))"
    }

    /// `[.warning: SeasonalBanner(title: …, text: …)]`, in `ItemSchema.eventBanners` order.
    private func banners(_ banners: [SeasonalEvent.Banner]) -> String {
        let ordered = ItemSchema.eventBanners.compactMap { key in banners.first { $0.key == key } }
        guard !ordered.isEmpty else { return "[:]" }
        return "[" + ordered.map { ".\($0.key): SeasonalBanner(title: \(literal($0.title)), text: \(literal($0.text)))" }
            .joined(separator: ", ") + "]"
    }

    // MARK: - Declarations

    /// An enum with one case per id, followed by its members. A case's raw
    /// value is its id unless `rawValues` gives one per id.
    private func enumDecl(
        _ name: String, _ conformances: String, _ ids: [String], rawValues: [String]? = nil, _ members: [String]
    ) -> String {
        let cases = ids.enumerated().map { index, id in
            if let raw = rawValues?[index] { return "    case \(caseName(id)) = \(raw)\n" }
            return unquotedCaseName(id) == id ? "    case \(caseName(id))\n" : "    case \(caseName(id)) = \(literal(id))\n"
        }
        let body = members.filter { !$0.isEmpty }.map { "\n" + $0 }.joined()
        return "\n\(access)enum \(name): \(conformances) {\n\(cases.joined())\(body)}\n"
    }

    /// Decoding that also accepts each building's `legacyIds`.
    private func codable(aliases: [(legacy: String, current: String)]) -> String {
        let canonical = aliases.isEmpty ? "raw" : "switch raw {\n"
            + aliases.map { "        case \(literal($0.legacy)): \(literal($0.current))\n" }.joined()
            + "        default: raw\n        }"
        return """
            \(access)init(from decoder: Decoder) throws {
                let raw = try decoder.singleValueContainer().decode(String.self)
                let canonical = \(canonical)
                guard let kind = BuildingKind(rawValue: canonical) else {
                    throw DecodingError.dataCorrupted(
                        .init(codingPath: decoder.codingPath, debugDescription: "Unknown BuildingKind raw value: \\(raw)")
                    )
                }
                self = kind
            }

            \(access)func encode(to encoder: Encoder) throws {
                var container = encoder.singleValueContainer()
                try container.encode(rawValue)
            }

        """
    }

    /// A catalog whose specs come from one exhaustive `switch`, built once:
    /// `all` in case order, and `spec(for:)` reads the stored table.
    private func catalog(_ name: String, spec: String, for parameter: String, of type: String, _ values: [(String, String)]) -> String {
        "\n\(access)enum \(name) {\n"
            + "    \(access)static let all: [\(spec)] = \(type).allCases.map(makeSpec)\n"
            + "    private static let specs = Dictionary(uniqueKeysWithValues: all.map { ($0.\(parameter), $0) })\n\n"
            + "    \(access)static func spec(for \(parameter): \(type)) -> \(spec) {\n"
            + "        specs[\(parameter)] ?? makeSpec(\(parameter))\n    }\n\n"
            + function("private static func makeSpec(_ \(parameter): \(type)) -> \(spec)", over: parameter, values)
            + "}\n"
    }

    /// A computed property as one exhaustive `switch`, one case per line.
    private func property(_ name: String, _ type: String, _ values: [(String, String)]) -> String {
        values.isEmpty ? "" : function("\(access)var \(name): \(type)", over: "self", values)
    }

    /// `signature` whose body switches over `subject`. Case patterns are
    /// ids turned into `.caseName` unless `quoted` is false.
    private func function(_ signature: String, over subject: String, _ values: [(String, String)], quoted: Bool = true) -> String {
        let cases = values.map { pattern, value in
            "        case \(quoted ? ".\(caseName(pattern))" : pattern): \(value)\n"
        }
        return "    \(signature) {\n        switch \(subject) {\n\(cases.joined())        }\n    }\n"
    }
}
